// visualization.js – creates bubble chart and linked table

// Dimensions
const width = 600;
const height = 620;

// Append SVG for bubble chart
const svg = d3.select('#bubbleChart')
  .append('svg')
  .attr('width', width)
  .attr('height', height);

// Tooltip div (hidden by default)
const tooltip = d3.select('body')
  .append('div')
  .attr('class', 'tooltip')
  .style('opacity', 0);

// Load CSV data
d3.csv('/output/data/stock-descriptions.csv').then(data => {
  // Parse numeric market cap (remove commas, handle empty)
  data.forEach(d => {
    d.marketCap = d.marketCap ? +d.marketCap.replace(/[^0-9.]/g, '') : null;
    d.isETF = d.type && d.type.toUpperCase() === 'ETF';
  });

  // Create a list of unique sectors
  const sectors = Array.from(new Set(data.map(d => d.sector))).filter(s => s);
  const sectorScale = d3.scalePoint()
    .domain(sectors)
    .range([100, width - 100]);

  // Radius scale – based on market cap, fallback for ETFs
  const capValues = data.filter(d => d.marketCap).map(d => d.marketCap);
  const rScale = d3.scaleSqrt()
    .domain([d3.min(capValues), d3.max(capValues)])
    .range([8, 40]);
  const etfRadius = 12; // uniform size for ETFs

  // Color scale for sectors
  const color = d3.scaleOrdinal(d3.schemeCategory10).domain(sectors);

  // Create simulation
  const simulation = d3.forceSimulation(data)
    .force('x', d3.forceX(d => sectorScale(d.sector)).strength(0.2))
    .force('y', d3.forceY(height / 2).strength(0.05))
    .force('collide', d3.forceCollide(d => (d.isETF ? etfRadius : rScale(d.marketCap)) + 2))
    .stop();

  // Run the simulation a few times to settle positions
  for (let i = 0; i < 300; ++i) simulation.tick();

  // Draw bubbles
  const node = svg.selectAll('g')
    .data(data)
    .enter()
    .append('g')
    .attr('transform', d => `translate(${d.x},${d.y})`)
    .style('cursor', d => d.isETF ? 'default' : 'pointer');

  node.append('circle')
    .attr('r', d => d.isETF ? etfRadius : rScale(d.marketCap))
    .attr('fill', d => color(d.sector))
    .attr('stroke', '#333')
    .attr('stroke-width', 1)
    .on('mouseover', function(event, d) {
      if (d.isETF) return; // no tooltip for ETFs
      tooltip.transition().duration(200).style('opacity', .9);
      tooltip.html(`<strong>${d.ticker}</strong><br/>${d.name}<br/>Sector: ${d.sector}`)
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 28) + 'px');
    })
    .on('mouseout', function() {
      tooltip.transition().duration(200).style('opacity', 0);
    })
    .on('click', function(event, d) {
      // Highlight corresponding table row
      d3.selectAll('#stockTable tr').classed('highlight', row => row.__data__.ticker === d.ticker);
    });

  // Add ticker labels
  node.append('text')
    .attr('text-anchor', 'middle')
    .attr('dy', '.35em')
    .attr('pointer-events', 'none')
    .style('font-size', d => (d.isETF ? 8 : 10) + 'px')
    .text(d => d.ticker);

  // ---- LEGEND ----
  const legend = svg.append('g')
    .attr('transform', `translate(20,20)`);
  sectors.forEach((sec, i) => {
    const g = legend.append('g').attr('transform', `translate(0,${i * 20})`);
    g.append('rect')
      .attr('width', 12)
      .attr('height', 12)
      .attr('fill', color(sec));
    g.append('text')
      .attr('x', 16)
      .attr('y', 10)
      .style('font-size', '12px')
      .text(sec);
  });

  // ---- TABLE ----
  const table = d3.select('#stockTable');
  const tbody = table.select('tbody');

  const formatCap = d => {
    if (!d.marketCap) return '';
    const trillion = 1e12, billion = 1e9, million = 1e6;
    if (d.marketCap >= trillion) return (d.marketCap / trillion).toFixed(2) + 'T';
    if (d.marketCap >= billion) return (d.marketCap / billion).toFixed(2) + 'B';
    if (d.marketCap >= million) return (d.marketCap / million).toFixed(2) + 'M';
    return d.marketCap;
  };

  const rows = tbody.selectAll('tr')
    .data(data)
    .enter()
    .append('tr')
    .on('click', function(event, d) {
      // Highlight bubble
      d3.selectAll('circle').classed('highlight', node => node.__data__.ticker === d.ticker);
      // Highlight row
      d3.selectAll('#stockTable tr').classed('highlight', row => row.__data__.ticker === d.ticker);
    });

  rows.append('td').text(d => d.ticker);
  rows.append('td').text(d => d.name);
  rows.append('td').text(d => d.sector);
  rows.append('td').text(d => formatCap(d));
});
EOF
